namespace BinhMinhParametric {
 public static partial class Builder {
  static void Verify(UIApplication ui){
   Log("BEGIN PARAMETRIC CONNECTION VERIFICATION");var results=new List<string>{"Series,Family,Type,Test,Result,Details"};var d=ui.Application.NewProjectDocument(@"C:\ProgramData\Autodesk\RVT 2024\Templates\Default_M_ENU.rte");
   var previews=new Dictionary<string,XYZ>();try{
    Library.Load(d);int families=new FilteredElementCollector(d).OfClass(typeof(Family)).Cast<Family>().Count(f=>f.Name.StartsWith("BMP_"));int types=new FilteredElementCollector(d).OfClass(typeof(FamilySymbol)).Cast<FamilySymbol>().Count(s=>s.Family.Name.StartsWith("BMP_"));if(families!=14||types!=131)throw new Exception("Expected 14 families and 131 types; actual="+families+"/"+types);
    int segmentCount=new FilteredElementCollector(d).OfClass(typeof(PipeSegment)).Count();Library.Load(d);if(new FilteredElementCollector(d).OfClass(typeof(PipeSegment)).Count()!=segmentCount)throw new Exception("Repeated setup duplicated pipe segments");results.Add("All,,,Load twice,PASS,14 families and 131 types; no duplicated segments");
    var level=new FilteredElementCollector(d).OfClass(typeof(Level)).FirstElementId();var system=Library.System(d,MEPSystemClassification.DomesticColdWater);int index=0;
    foreach(string series in new[]{"PVC","PPR10","PPR20"}){
     var pt=new FilteredElementCollector(d).OfClass(typeof(PipeType)).Cast<PipeType>().First(p=>p.Name.StartsWith("BMP ")&&Library.Series(p)==series);
     foreach(var r in Rows().Where(r=>r.Mat==(series=="PVC"?"PVC":"PPR"))){
      XYZ o=V((index%12)*4000,(index/12)*4000,1000);index++;using(var t=new Transaction(d,"Connect "+series+" "+r.Family+" "+r.Type)){
       t.Start();var options=t.GetFailureHandlingOptions();options.SetFailuresPreprocessor(new Errors());options.SetClearAfterRollback(true);t.SetFailureHandlingOptions(options);
       try{
        var network=new BoundedNetwork(d,root,new ElementId[0]);var a=network.CreatePipe(system,pt.Id,level,r.DN,o-V(1500,0),o);var check=new List<FamilyInstance>();
        if(r.Kind=="Cap"){d.Regenerate();PlumbingUtils.PlaceCapOnOpenEnds(d,a.Id,ElementId.InvalidElementId);d.Regenerate();check=a.ConnectorManager.Connectors.Cast<Connector>().SelectMany(c=>c.AllRefs.Cast<Connector>()).Where(c=>c.Owner is FamilyInstance).Select(c=>(FamilyInstance)c.Owner).GroupBy(f=>f.Id.Value).Select(g=>g.First()).ToList();if(check.Count!=2)throw new Exception("Both ends not capped");}
        else{XYZ direction=r.Kind.Contains("Tee")?XYZ.BasisX:r.Kind.StartsWith("Elbow")?new XYZ(Math.Cos(r.Angle*Math.PI/180),Math.Sin(r.Angle*Math.PI/180),0):XYZ.BasisX;var b=network.CreatePipe(system,pt.Id,level,r.Kind.Contains("Tee")?r.DN:r.DN2,o,o+direction*M(1500));var ps=new List<Pipe>{a,b};if(r.Kind.Contains("Tee"))ps.Add(network.CreatePipe(system,pt.Id,level,r.DN2,o,o+V(0,1500)));check.Add(network.Connect(ps,o,r.Mat));}
        d.Regenerate();if(t.Commit()!=TransactionStatus.Committed)throw new Exception("Transaction rolled back");
        foreach(var fit in check){if(fit.Symbol.Family.Name!=r.Family||fit.Symbol.Name!=r.Type)throw new Exception("Wrong family/type "+fit.Symbol.Family.Name+" "+fit.Symbol.Name);foreach(Connector fc in fit.MEPModel.ConnectorManager.Connectors){var peers=fc.AllRefs.Cast<Connector>().Where(c=>c.Owner is Pipe).ToList();if(!fc.IsConnected||peers.Count!=1||fc.Origin.DistanceTo(peers[0].Origin)>M(.1)||Math.Abs(fc.Radius-peers[0].Radius)>M(.01)||fc.CoordinateSystem.BasisZ.DotProduct(peers[0].CoordinateSystem.BasisZ)>-.9999)throw new Exception("Connector mismatch after commit");}}
        results.Add(series+","+r.Family+","+r.Type+",Connection,PASS,Correct family type and coincident connected ports");
        if((series=="PVC"&&r.Kind=="Elbow90"&&r.DN==34)||(series=="PPR20"&&r.Kind=="Elbow45"&&r.DN==32)||(series=="PVC"&&r.Kind=="ReducingTee"&&r.DN==60&&r.DN2==34)||(series=="PPR20"&&r.Kind=="Reducer"&&r.DN==32&&r.DN2==20))previews[r.Family+" "+r.Type]=o;
       }catch(Exception ex){if(t.GetStatus()==TransactionStatus.Started)t.RollBack();results.Add(series+","+r.Family+","+r.Type+",Connection,FAIL,\""+ex.Message.Replace("\"","'")+"\"");Log("CONNECTION FAIL "+r.Family+" "+r.Type+" "+ex.Message);}
      }
      File.WriteAllLines(Path.Combine(root,"output","ParametricConnectionTests.csv"),results);
     }
    }
    VerifyTypeChanges(d,results);VerifyVertical(d,results,level,system);
    var previewViews=new List<ElementId>();using(var t=new Transaction(d,"Parametric library presentation")){t.Start();var u=d.GetUnits();u.SetFormatOptions(SpecTypeId.Length,new FormatOptions(UnitTypeId.Millimeters));u.SetFormatOptions(SpecTypeId.PipeSize,new FormatOptions(UnitTypeId.Millimeters));d.SetUnits(u);var vt=new FilteredElementCollector(d).OfClass(typeof(ViewFamilyType)).Cast<ViewFamilyType>().First(v=>v.ViewFamily==ViewFamily.ThreeDimensional);var view=View3D.CreateIsometric(d,vt.Id);view.Name="BMP - Thu vien 14 family nhieu Type";view.DetailLevel=ViewDetailLevel.Fine;view.DisplayStyle=DisplayStyle.Shading;foreach(var p in previews){var closeup=View3D.CreateIsometric(d,vt.Id);closeup.Name="BMP - "+p.Key;closeup.DetailLevel=ViewDetailLevel.Fine;closeup.DisplayStyle=DisplayStyle.Shading;closeup.SetBackground(ViewDisplayBackground.CreateGradient(new Color(255,255,255),new Color(255,255,255),new Color(255,255,255)));closeup.Discipline=ViewDiscipline.Plumbing;closeup.SetSectionBox(new BoundingBoxXYZ{Min=p.Value-V(250,250,200),Max=p.Value+V(250,250,200)});closeup.IsSectionBoxActive=true;previewViews.Add(closeup.Id);}t.Commit();}
    d.SaveAs(Path.Combine(root,"output","BMP_Parametric_Revit2024_mm_v2.rvt"),new SaveAsOptions{OverwriteExistingFile=true,MaximumBackups=1});Log("PARAMETRIC PROJECT SAVED");var images=new ImageExportOptions{FilePath=Path.Combine(root,"output","ParametricPreview"),ExportRange=ExportRange.SetOfViews,HLRandWFViewsFileType=ImageFileType.PNG,ShadowViewsFileType=ImageFileType.PNG,ZoomType=ZoomFitType.FitToPage,PixelSize=1400};images.SetViewsAndSheets(previewViews);d.ExportImage(images);
   }catch(Exception ex){Log("VERIFICATION FATAL "+ex);results.Add("All,,,Workflow,FAIL,\""+ex.Message.Replace("\"","'")+"\"");}finally{File.WriteAllLines(Path.Combine(root,"output","ParametricConnectionTests.csv"),results);if(ui.ActiveUIDocument==null||!ui.ActiveUIDocument.Document.Equals(d))d.Close(false);else Log("Verified document remains open for inspection");}
   Log("PARAMETRIC VERIFY FINISHED rows="+results.Count);
   if(results.Skip(1).All(s=>s.Contains(",PASS,")))BinhMinh.ParametricConnect.App.AddToSession(ui);
  }
  static void Finish(UIApplication ui){
   foreach(string name in new[]{"ParametricFlexTests.csv","ParametricConnectionTests.csv"}){var lines=File.ReadAllLines(Path.Combine(root,"output",name)).Skip(1).ToList();if(lines.Count==0||lines.Any(s=>!s.Contains(",PASS,")))throw new Exception("Report has unresolved results: "+name);Log("FINAL REPORT "+name+" PASS="+lines.Count);}
   var path=Path.Combine(root,"output","BMP_Parametric_Revit2024_mm_v2.rvt");var active=ui.ActiveUIDocument;var opened=active!=null&&string.Equals(active.Document.PathName,path,StringComparison.OrdinalIgnoreCase)?active:ui.OpenAndActivateDocument(path);using(var transaction=new Transaction(opened.Document,"Final presentation settings")){transaction.Start();foreach(var v in new FilteredElementCollector(opened.Document).OfClass(typeof(View3D)).Cast<View3D>().Where(v=>v.Name.StartsWith("BMP -"))){Log("VIEW BEFORE "+v.Name+" discipline="+v.Discipline);foreach(var cat in new[]{BuiltInCategory.OST_PipeCurvesCenterLine,BuiltInCategory.OST_PipeFittingCenterLine,BuiltInCategory.OST_CLines}){var category=Category.GetCategory(opened.Document,cat);if(category!=null&&v.CanCategoryBeHidden(category.Id))v.SetCategoryHidden(category.Id,true);}v.Discipline=ViewDiscipline.Plumbing;v.DetailLevel=ViewDetailLevel.Fine;v.DisplayStyle=DisplayStyle.Shading;v.SetBackground(ViewDisplayBackground.CreateGradient(new Color(255,255,255),new Color(255,255,255),new Color(255,255,255)));}transaction.Commit();}opened.Document.Save();var imageViews=new FilteredElementCollector(opened.Document).OfClass(typeof(View3D)).Cast<View3D>().Where(v=>v.Name.StartsWith("BMP - BMP_")).Select(v=>v.Id).ToList();var export=new ImageExportOptions{FilePath=Path.Combine(root,"output","ParametricPreview"),ExportRange=ExportRange.SetOfViews,HLRandWFViewsFileType=ImageFileType.PNG,ShadowViewsFileType=ImageFileType.PNG,ZoomType=ZoomFitType.FitToPage,PixelSize=1400};export.SetViewsAndSheets(imageViews);opened.Document.ExportImage(export);var view=new FilteredElementCollector(opened.Document).OfClass(typeof(View3D)).Cast<View3D>().First(v=>v.Name.StartsWith("BMP - BMP_PVC_ReducingTee"));opened.RequestViewChange(view);BinhMinh.ParametricConnect.App.AddToSession(ui);foreach(var panel in ui.GetRibbonPanels("KMep"))if(panel.Name=="Bình Minh 2024")panel.Visible=false;File.WriteAllText(Path.Combine(root,"parametric.complete"),DateTime.Now.ToString("O"));Log("PARAMETRIC FINISH COMPLETE");
  }
  static List<XYZ> Local(Row r){if(r.Kind.StartsWith("Elbow")){double a=r.Angle*Math.PI/180,rad=r.H/Math.Tan(a/2);return new List<XYZ>{V(0,-rad),V(rad*Math.Sin(a),-rad*Math.Cos(a))};}if(r.Kind.Contains("Tee"))return new List<XYZ>{V(-r.H,0),V(r.H,0),V(0,r.H2)};if(r.Kind=="Cap")return new List<XYZ>{V(-r.L,0)};return new List<XYZ>{V(-r.L/2,0),V(r.L/2,0)};}
  static void VerifyTypeChanges(Document d,List<string> results){int index=0;foreach(var group in Rows().GroupBy(r=>r.Family)){
   using(var t=new Transaction(d,"Change type "+group.Key)){t.Start();var opt=t.GetFailureHandlingOptions();opt.SetFailuresPreprocessor(new Errors());opt.SetClearAfterRollback(true);t.SetFailureHandlingOptions(opt);try{
    XYZ origin=V(100000,index++*3000,1000);FamilyInstance fit=null;foreach(var r in group){var s=new FilteredElementCollector(d).OfClass(typeof(FamilySymbol)).Cast<FamilySymbol>().First(x=>x.Family.Name==r.Family&&x.Name==r.Type);if(!s.IsActive)s.Activate();d.Regenerate();if(fit==null){if(r.Kind=="Cap")fit=d.Create.NewFamilyInstance(origin,s,Autodesk.Revit.DB.Structure.StructuralType.NonStructural);else{var plan=new FilteredElementCollector(d).OfClass(typeof(ViewPlan)).Cast<ViewPlan>().First(v=>!v.IsTemplate);var host=d.Create.NewReferencePlane(origin-XYZ.BasisX,origin+XYZ.BasisX,-XYZ.BasisY,plan);fit=d.Create.NewFamilyInstance(host.GetReference(),origin,XYZ.BasisX,s);}}else{var changed=fit.ChangeTypeId(s.Id);if(changed!=ElementId.InvalidElementId)fit=(FamilyInstance)d.GetElement(changed);}d.Regenerate();var ports=fit.MEPModel.ConnectorManager.Connectors.Cast<Connector>().ToList();var local=Local(r);if(ports.Count!=local.Count)throw new Exception("Port count changed");for(int i=0;i<local.Count;i++){var target=fit.GetTransform().OfPoint(local[i]);var port=ports.OrderBy(c=>c.Origin.DistanceTo(target)).First();double dn=(r.Kind=="Reducer"&&i==1)||(r.Kind=="ReducingTee"&&i==2)?r.DN2:r.DN;if(port.Origin.DistanceTo(target)>M(.02)||Math.Abs(port.Radius*2-M(dn))>M(.01))throw new Exception("Type change port mismatch: "+r.Type);}results.Add(r.Mat+","+r.Family+","+r.Type+",Change Type in project,PASS,Geometry and connector positions and sizes follow new type");}
    if(t.Commit()!=TransactionStatus.Committed)throw new Exception("Type change commit failed");
   }catch(Exception ex){if(t.GetStatus()==TransactionStatus.Started)t.RollBack();results.Add("All,"+group.Key+",,Change Type in project,FAIL,\""+ex.Message.Replace("\"","'")+"\"");Log("TYPE CHANGE FAIL "+group.Key+" "+ex.Message);}}
  }}
  static void VerifyVertical(Document d,List<string> results,ElementId level,ElementId system){int index=0;foreach(string mat in new[]{"PVC","PPR"})foreach(double angle in new[]{45.0,90.0}){
   using(var t=new Transaction(d,"Vertical connection")){t.Start();var opt=t.GetFailureHandlingOptions();opt.SetClearAfterRollback(true);opt.SetFailuresPreprocessor(new Errors());t.SetFailureHandlingOptions(opt);try{var pt=new FilteredElementCollector(d).OfClass(typeof(PipeType)).Cast<PipeType>().First(p=>p.Name.StartsWith(mat=="PVC"?"BMP PVC":"BMP PPR PN20"));var network=new BoundedNetwork(d,root,new ElementId[0]);XYZ at=V(120000,index++*4000,3000);double dn=mat=="PVC"?34:32;var a=network.CreatePipe(system,pt.Id,level,dn,at-V(0,0,1500),at);var b=network.CreatePipe(system,pt.Id,level,dn,at,at+V(Math.Sin(angle*Math.PI/180)*1500,0,Math.Cos(angle*Math.PI/180)*1500));var fit=network.Connect(new List<Pipe>{b,a},at,mat);if(t.Commit()!=TransactionStatus.Committed)throw new Exception("Commit failed");if(fit.MEPModel.ConnectorManager.Connectors.Cast<Connector>().Any(c=>!c.IsConnected))throw new Exception("Lost vertical connection");results.Add(mat+",Elbow,"+dn+" mm,Vertical reversed "+angle+",PASS,Connected ports after commit");}catch(Exception ex){if(t.GetStatus()==TransactionStatus.Started)t.RollBack();results.Add(mat+",Elbow,,Vertical reversed "+angle+",FAIL,\""+ex.Message.Replace("\"","'")+"\"");}}}
  }
 }
}





